var app=angular.module("kycSoleProprietorshipApp",[]);app.service("kycSoleProprietorshipService",["$http",function($http){var protocal=window.location.protocol;var host=window.location.host;var uRl=protocal+"//"+host+"/";this.save=function(data){var formData=new FormData;angular.forEach(data,function(value,key){if(value instanceof FileList){for(let i=0;i<value.length;i++){formData.append(key,value[i])}}else if(Array.isArray(value)){angular.forEach(value,function(file){formData.append(key+"[]",file)})}else{formData.append(key,value)}});return $http.post(uRl+"kyc-sole-proprietorship/save",formData,{transformRequest:angular.identity,headers:{"Content-Type":undefined}})};this.getAllKYCRecords=function(){return $http.get(uRl+"kyc-sole-proprietorship/getAllKycRecord")};this.getAllBranchListOfCOPs=function(userName){return $http.get(uRl+"kyc-sole-proprietorship/getAllBranchListOfCOPs/"+userName)};this.getAllBranchListOfBOM=function(userName){return $http.get(uRl+"kyc-sole-proprietorship/getAllBranchListOfBOM/"+userName)};this.get=function(id){return $http.get(uRl+"kyc-sole-proprietorship/get/"+id)};this.delete=function(id){return $http.delete(uRl+"kyc-sole-proprietorship/delete/"+id)};this.getJsonFile=function(){return $http.get(uRl+"kyc-sole-proprietorship/getJsonFile")};this.getAadhar=function(adharNo){return $http.get(uRl+"kyc-sole-proprietorship/getAadhar/"+adharNo)};this.getRecordByCode=function(code){return $http.get(uRl+"kyc-sole-proprietorship/getRecordByCode/"+code)};this.update=function(data){var formData=new FormData;angular.forEach(data,function(value,key){if(value instanceof FileList){for(let i=0;i<value.length;i++){formData.append(key,value[i])}}else if(Array.isArray(value)){angular.forEach(value,function(file){formData.append(key+"[]",file)})}else{formData.append(key,value)}});return $http.put(uRl+"kyc-sole-proprietorship/update",formData,{transformRequest:angular.identity,headers:{"Content-Type":undefined}})};this.updateCOPs=function(data){var formData=new FormData;angular.forEach(data,function(value,key){if(value instanceof FileList){for(let i=0;i<value.length;i++){formData.append(key,value[i])}}else if(Array.isArray(value)){angular.forEach(value,function(file){formData.append(key+"[]",file)})}else{formData.append(key,value)}});return $http.put(uRl+"kyc-sole-proprietorship/updateCOPs",formData,{transformRequest:angular.identity,headers:{"Content-Type":undefined}})}}]);